import {sampleQuote} from './sample-quote.js';
import {policyArtwork} from './visuals.js';
import {premiumSummary,premiumBreakdown} from './premium-components.js';
import {reviewRow,reviewGroup,reviewSection,coverageContext,coverageOption,quotationAddon,actionBar} from './insurance-components.js';
import {createFormComponents} from './components.js';
import {button,notice,documentRow} from './ui.js';
import {icon} from './icons.js';

const state={empty:'',complete:'Alex Tan',invalid:'alex@',readonly:'31 Dec 2026',disabled:'',classification:'General Medical Practitioner',answer:'Yes',consentExample:true,answers:{}};
const errors={invalid:'Enter a valid email address.'};
const forms=createFormComponents(()=>state,()=>errors);
const section=(id,number,title,body)=>`<section class="system-section" id="${id}"><header><span>${number}</span><h2>${title}</h2></header>${body}</section>`;
const specimen=(title,body)=>`<div class="system-specimen"><h3>${title}</h3>${body}</div>`;
const table=rows=>`<table class="system-table"><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th><td>${value}</td></tr>`).join('')}</tbody></table>`;
const colors=[['Brand teal','--brand-primary','#08A5B5'],['Brand navy','--brand-secondary','#132766'],['Text','--content-primary','#172536'],['Secondary text','--content-secondary','#607080'],['Selected','--surface-selection','#F0FAFA'],['Canvas','--surface-page','#F3F6F6']];
const sections=[
section('foundations','01','Foundations',`<div class="system-palette">${colors.map(([name,token,hex])=>`<div class="system-swatch"><i style="--swatch:var(${token})"></i><div><span>${name}</span><code>${hex}</code></div><code class="swatch-token">${token}</code><div class="swatch-role">${name==='Brand teal'?'Primary actions':name==='Brand navy'?'Brand identity and headings':name==='Text'?'Labels and body text':name==='Secondary text'?'Supporting information':name==='Selected'?'Selected options':'Application background'}</div></div>`).join('')}</div><p>Semantic roles separate brand color from text, selection, focus and feedback. Teal buttons use dark text; links use the darker accessible teal.</p>${table([['Spacing','4 · 8 · 12 · 16 · 20 · 24 · 32 · 40 · 48 · 64px'],['Geometry','8px controls · 12px form surfaces · 28px desktop panel inset'],['Targets','46px desktop inputs · 48px mobile inputs · 44px minimum targets'],['Motion','140ms feedback · 200ms transitions · reduced motion respected']])}`),
section('type','02','Typography',`<div class="system-type"><small>Kanit · Page title · 30 / 36</small><p style="font:400 var(--text-title)/1.2 var(--font-heading);letter-spacing:var(--tracking-heading)">Your coverage</p></div><div class="system-type"><small>Kanit · Section title · 18 / 25</small><p style="font:500 var(--text-section)/1.4 var(--font-heading)">Personal particulars</p></div><div class="system-type"><small>Inter · Body · 14 / 22</small><p>Chubb Elite Medical Malpractice Insurance</p></div><div class="system-type"><small>Inter · Label · 13 / 20</small><p class="field-label">Insurance Start Date</p></div><div class="system-type"><small>Inter · Supporting text · 12 / 19</small><p class="hint">Coverage ends on 31 December.</p></div>`),
section('controls','03','Form controls',`<div class="system-grid">${specimen('Default',forms.field('empty','Full Name as per IC'))}${specimen('Completed',forms.field('complete','Full Name as per IC'))}${specimen('Error',forms.field('invalid','Your Email',{type:'email'}))}${specimen('Read only',forms.field('readonly','Insurance End Date',{readonly:true}))}${specimen('Calculated information','<div class="field calculated-field"><span class="field-label" id="calculated-label">Insurance End Date</span><output aria-labelledby="calculated-label">31 Dec 2026</output></div>')}${specimen('Disabled',forms.field('disabled','Limit Of Liability',{disabled:true}))}${specimen('Native selection',forms.select('classification','Classification',['General Medical Practitioner','General Dentist']))}${specimen('Date',forms.field('sampleDate','Insurance Start Date',{type:'date'}))}${specimen('Long-form response',forms.textarea('sampleDetails','Please provide details below',{rows:3}))}</div><p>Persistent labels, native input behavior and linked errors. Tab into the controls to inspect keyboard focus. Mobile inputs use 16px text.</p>`),
section('selection','04','Selection',`<div class="system-grid">${specimen('Explicit choice',forms.question('answer','Do you own a clinic?'))}${specimen('Optional coverage',forms.check('consentExample','Add This Recommended Coverage'))}</div><p>Selection uses both a native control and a visible border. Consent remains separate from links to legal documents.</p>`),
section('actions','05','Actions',`<div class="system-stack">${specimen('Hierarchy',`<div class="system-row">${button('Continue',{trailing:'arrow'})}${button('Edit details',{variant:'secondary',leading:'edit'})}${button('Back',{variant:'quiet',leading:'back'})}</div>`)}${specimen('Unavailable and pending',`<div class="system-row">${button('Unavailable',{disabled:true})}${button('Connecting…',{loading:true})}${button('Edit',{variant:'secondary',size:'small'})}</div>`)}</div><p>One primary action per task. Disabled and busy actions cannot be submitted; icons supplement the label.</p>`),
section('feedback','06','Feedback',`<div class="system-stack">${notice('<p>No information has been submitted.</p>',{tone:'error',title:'Service unavailable'})}${notice('<p>Coverage ends on 31 December.</p>',{tone:'info'})}${notice('<p>Your changes are saved in this tab.</p>',{tone:'success'})}</div><p>These are component examples, not service outcomes. Live error notices use alerts; progress uses a polite status announcement.</p>`),
section('surfaces','07','Insurance compositions',`<div class="system-stack">${coverageContext({classification:'General Medical Practitioner',liability:'RM 1,000,000',period:'1 Nov 2026 – 31 Dec 2026',editable:false})}${quotationAddon({price:300,sample:true,id:'dsClinic',title:'Clinic Medical Malpractice Insurance',selected:true,description:'The application uses the source explanation for the selected practice details.',details:forms.select('exampleLimit','Clinic Limit Of Liability',['RM 500,000','RM 1,000,000'])})}${specimen('Application review',reviewSection('example','Your coverage','',reviewGroup('',reviewRow('Classification','General Medical Practitioner')+reviewRow('Limit Of Liability','RM 1,000,000'))))}${specimen('Policy documents','<div class="document-list">'+documentRow({title:'Product Disclosure Sheet (English)',href:'https://my-individualindemnity.doctorshield.com/assets/Product_Disclosure_Sheet_English.pdf',type:'PDF'})+'</div>')}${specimen('Task action area',actionBar(button('Back',{variant:'quiet',leading:'back'}),button('Continue',{trailing:'arrow'})))}<details class="disclosure"><summary>Important Notices to the Applicants</summary><div class="disclosure-body"><p class="hint">The application displays the complete source notices and declaration wording.</p></div></details></div><p>Coverage context, selectable product and action area are rendered by the same insurance component module used in the application.</p>`),
section('pricing','08','Pricing & disclosure',`<p>The total stays visible. The calculation stays one action away.</p><div class="system-preview-bar">${premiumSummary(sampleQuote())}${button('Continue',{disabled:true,trailing:'arrow'})}</div><p>Unavailable pricing is never shown as zero. Illustrative amounts show the same pricing components as the application. They are not insurer rates.</p>${specimen('Breakdown anatomy',premiumBreakdown(sampleQuote()))}${table([['Currency','MYR · tabular numerals · two decimal places'],['Amount source','All six monetary values must come from a complete quotation response.'],['Desktop','Centred dialog with a close control and keyboard focus containment.'],['Mobile','Bottom sheet, safe-area padding and a scrollable breakdown.']])}`),
section('visuals','09','Visual language',`<div class="system-illustration">${policyArtwork()}<p>A medical-practice illustration supports the application rail. Keep transactional controls and mobile forms free of decorative artwork.</p></div><div class="system-icon-spec"><div>${icon('shield',48)}</div><p><strong>One stroke. One optical grid.</strong><br>24px grid · 1.65px stroke · rounded terminals</p></div><p>Use icons to identify an action or category. Keep a visible label on unfamiliar actions. Decorative icons are hidden from assistive technology.</p><div class="system-icons">${['arrow','back','chevron','shield','info','calendar','check','file','user','lock','plus','close','mail','phone','building','edit','search','external'].map(name=>`<div class="system-icon">${icon(name,22)}<span>${name}</span></div>`).join('')}</div>`),
section('behavior','10','Behavior',table([['Keyboard','Native Tab, Enter, Space and arrow-key behavior. Dialogs use native focus containment and Escape dismissal.'],['Errors','Linked inline message, visible invalid state, error summary and first-invalid-field focus.'],['Responsive','Desktop navigation rail; compact progress on mobile. Single-column fields at narrow widths.'],['Accessibility','Text contrast, persistent labels, visible focus, reduced motion and forced-colors fallback. Full accessibility certification is not claimed.'],['Content','Existing product wording and legal text are preserved. Supporting details are disclosed when useful.'],['Services','Pricing, OTP and payment remain unconnected. No success is fabricated.']]))
];
document.querySelector('#system-sections').innerHTML=sections.join('');

const semanticRoles=[['Primary action','--action-primary'],['Action text','--content-on-action'],['Text link','--content-action'],['Input boundary','--border-control'],['Selected boundary','--border-selection'],['Focus outline','--focus-outline'],['Error boundary','--state-danger-border'],['Success boundary','--state-success-border'],['Warning boundary','--state-warning-border'],['Information boundary','--state-info-border'],['Error','--state-danger'],['Success','--state-success'],['Warning','--state-warning'],['Disabled text','--state-disabled']];
const tokenValues=getComputedStyle(document.documentElement);
document.querySelector('#foundations').insertAdjacentHTML('beforeend','<h3 class="system-subtitle">Interaction roles</h3><div class="system-token-list">'+semanticRoles.map(([name,token])=>'<div class="system-token-row"><i style="background:var('+token+')" aria-hidden="true"></i><span>'+name+'</span><code>'+token+'</code><small>'+tokenValues.getPropertyValue(token).trim()+'</small></div>').join('')+'</div><h3 class="system-subtitle">Spacing rhythm</h3><div class="system-spacing">'+[4,8,12,16,24,32,48].map(n=>'<div><span>'+n+'px</span><i style="width:'+n+'px" aria-hidden="true"></i></div>').join('')+'</div>');
state.dsClinic=true;
document.querySelector('#dsClinic').checked=true;
document.querySelector('#dsClinic').addEventListener('change',event=>{const option=event.target.closest('.quotation-addon');option.classList.toggle('is-selected',event.target.checked);option.querySelector('.quotation-addon-choice span').textContent=event.target.checked?'Added to your coverage':'Add This Recommended Coverage';const status=option.querySelector('.addon-status');if(event.target.checked&&!status)option.querySelector('.quotation-addon-head').insertAdjacentHTML('beforeend','<span class="addon-status" aria-hidden="true">Selected</span>');else if(!event.target.checked)status?.remove();});

const navigationLinks=[...document.querySelectorAll('.system-nav a')];
const referenceSections=[...document.querySelectorAll('.system-section')];
const descriptions={foundations:'The roles behind every surface, border and interaction.',type:'A precise hierarchy for complex information.',controls:'Persistent labels. Clear input states. Useful feedback.',selection:'Make the choice obvious before and after selection.',actions:'One clear next step, with quieter supporting actions.',feedback:'Tell users what happened and what they can do next.',surfaces:'Patterns assembled from the same components as the portal.',pricing:'Visible totals, explicit availability and contextual detail.',visuals:'A restrained icon language with consistent proportions.',behavior:'Interaction contracts for a dependable experience.'};
function showSection(focus=false){const id=location.hash.slice(1);const current=referenceSections.find(s=>s.id===id)||referenceSections[0];referenceSections.forEach(s=>s.hidden=s!==current);navigationLinks.forEach(a=>{if(a.hash==='#'+current.id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('#library-title').textContent=current.querySelector('h2').textContent;document.querySelector('#library-description').textContent=descriptions[current.id];document.querySelector('#library-index').textContent=current.querySelector('header>span').textContent+' / 10';if(focus){document.querySelector('#library-title').focus();window.scrollTo({top:0,behavior:'instant'});}}
window.addEventListener('hashchange',()=>showSection(true));showSection();
// State specimens are demonstrations, never customer submissions.
document.querySelector('#invalid').addEventListener('input',event=>{const valid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(event.target.value);event.target.setAttribute('aria-invalid',String(!valid));document.querySelector('#invalid-error').hidden=valid;event.target.closest('.field').classList.toggle('has-error',!valid);});
const dialog=document.querySelector('#modal');let returnFocus;
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-action="premium-breakdown"]');if(trigger){returnFocus=trigger;dialog.classList.add('premium-dialog');dialog.innerHTML='<div class="modal-head"><h2 id="modal-title">Premium breakdown</h2><button class="icon-btn" type="button" aria-label="Close dialog" data-library-close>'+icon('close')+'</button></div><div class="modal-body">'+premiumBreakdown(sampleQuote())+'</div>';document.body.classList.add('premium-modal-open');dialog.showModal();}if(event.target.closest('[data-library-close]'))dialog.close();});
dialog.addEventListener('close',()=>{document.body.classList.remove('premium-modal-open');returnFocus?.focus();});

